const f = $input.first().json;
const n = Math.min(Number(f['기업 수']) || 10, 30);

const system = `You are a B2B market researcher.
List only real, currently operating companies.
If you are not confident a company exists, omit it.
If you do not know its official website domain, return an empty string for domain.
Never invent companies or domains.`;

const user = `검색 조건
- 산업: ${f['산업']}
- 국가: ${f['국가']}
- 기업 규모: ${f['기업 규모']}
- 제품/키워드: ${f['제품/키워드'] || '(없음)'}

위 조건에 맞는 기업을 최대 ${n}개 찾아줘.
각 기업마다 공식 웹사이트 도메인, 1~2문장 설명, 조건에 맞는 이유, 확신도(high/medium/low)를 포함해.`;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['companies'],
  properties: {
    companies: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'domain', 'description', 'fit_reason', 'confidence'],
        properties: {
          name: { type: 'string' },
          domain: { type: 'string' },
          description: { type: 'string' },
          fit_reason: { type: 'string' },
          confidence: { type: 'string', enum: ['high', 'medium', 'low'] }
        }
      }
    }
  }
};

return [{
  json: {
    body: {
      model: 'gpt-4.1-mini',
      temperature: 0.2,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'company_list', strict: true, schema }
      }
    }
  }
}];

const content = $input.first().json.choices[0].message.content;
const { companies } = JSON.parse(content);

// 도메인 정규화: 소문자, 프로토콜/www/경로 제거
const norm = (d) => (d || '')
  .toLowerCase().trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split(/[\/?#]/)[0];

const seen = new Set();
const out = [];
for (const c of companies) {
  const domain = norm(c.domain);
  const key = domain || c.name.toLowerCase().trim();
  if (seen.has(key)) continue;   // 같은 도메인(없으면 이름) 중복 제거
  seen.add(key);
  out.push({ json: { ...c, domain } });
}
return out;

const c = $json;
const f = $('Target Form').first().json;

const system = `You write short, personalized B2B cold outreach emails.
Rules:
- Use ONLY the facts given about the recipient company. Do not invent numbers, customers, news, or people.
- One clear reason why our product fits this company, one soft call to action.
- Body under 150 words (Korean: under 500 characters).
- No placeholders like [Name] or {{company}}.
- End with the sender signature exactly as given.
Return JSON: {"subject": string, "body": string}.`;

const user = `작성 언어: ${f['이메일 언어']}

[수신 기업]
- 이름: ${c.name}
- 도메인: ${c.domain || '(미상)'}
- 설명: ${c.description}
- 우리 조건에 맞는 이유: ${c.fit_reason}

[우리 제품 소개]
${f['우리 제품 소개']}

[발신자 서명]
${f['발신자 서명']}`;

return {
  json: {
    body: {
      model: 'gpt-4.1-mini',
      temperature: 0.5,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ],
      response_format: { type: 'json_object' }
    }
  }
};

const f = $('Target Form').first().json;
const companies = $('Parse & Dedupe').all();

return $input.all().map((item, i) => {
  const c = companies[i].json;
  let draft = { subject: '', body: '' };
  let status = 'drafted';
  try {
    draft = JSON.parse(item.json.choices[0].message.content);
  } catch (e) {
    status = 'llm_failed';
  }
  return {
    json: {
      created_at: new Date().toISOString(),
      industry: f['산업'],
      country: f['국가'],
      company: c.name,
      domain: c.domain,
      description: c.description,
      fit_reason: c.fit_reason,
      confidence: c.confidence,
      subject: draft.subject || '',
      body: draft.body || '',
      status,
      verified: 'no'   // LLM이 만든 기업 리스트라 사람이 확인 전까지 no
    }
  };
});
